// Блог v5 (26.11.2026): 6 статей під продаж послуг; одноразово додаються в settings.site.posts
export const BLOG5 = [{"id": 12, "st": "pub", "img": "/assets/img/blog/lyttia-plastyku-lviv.webp", "tag": ["Виробництво", "Production"], "date": "2026-04-14", "slug": {"uk": "lyttia-plastykovykh-vyrobiv-na-zamovlennia-lviv", "en": "custom-plastic-injection-molding-lviv"}, "t": ["Лиття пластикових виробів на замовлення у Львові: ціна, терміни та мінімальний тираж", "Custom plastic injection molding in Lviv: price, lead times and minimum run"], "e": ["Скільки коштує лиття пластику на замовлення, від чого залежать ціна й терміни, який мінімальний тираж і як отримати розрахунок на виробництві PLASTIZA у Львові.", "What custom plastic molding costs, what drives price and lead time, what the minimum run is and how to get a quote from the PLASTIZA plant in Lviv."], "b": [[["p", "Коли компанії потрібна партія пластикових деталей — корпусів, заглушок, кріплень, фіксаторів чи технічних виробів, — перше питання завжди однакове: скільки це коштуватиме і як швидко буде готово. Відповідь залежить від кількох чинників, і якщо їх знати заздалегідь, можна і зекономити, і уникнути затримок."], ["p", "У цій статті пояснюємо, як формується ціна лиття пластикових виробів на замовлення, які терміни реальні, з якого тиражу лиття вигідне і що потрібно, щоб отримати точний розрахунок на нашому виробництві у Львові. Про саму послугу — на сторінці <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">«Лиття пластикових виробів»</a>."], ["h2", "Що ми відливаємо"], ["p", "На власних термопластавтоматах PLASTIZA відливає вироби з термопластів для будівництва, промисловості й побутового призначення:"], ["ul", "<li>технічні деталі, кріплення, втулки, заглушки;</li><li>корпуси й кришки;</li><li>будівельні вироби — фіксатори арматури, елементи опалубки;</li><li>деталі за кресленнями замовника або за зразком.</li>"], ["p", "Ми працюємо як із власними пресформами, так і з формами замовника. Як проходить процес від креслення до серії, ми описали в статті <a href=\"/blog/lyttia-pid-tyskom\" data-go=\"post\" data-a=\"3\">«Лиття пластмас під тиском»</a>."], ["h2", "З чого складається ціна лиття"], ["p", "Ціна виробу складається з кількох частин:"], ["ul", "<li><b>Матеріал і маса деталі.</b> Що важча деталь і дорожчий пластик, то більша частка сировини в ціні.</li><li><b>Час циклу.</b> Товсті стінки довше охолоджуються, а отже займають більше машинного часу на кожну деталь.</li><li><b>Кількість гнізд у пресформі.</b> Чотиригніздна форма дає чотири деталі за цикл і знижує ціну одиниці.</li><li><b>Пресформа.</b> Якщо форми ще немає, її вартість розподіляється на тираж або оплачується окремо.</li><li><b>Додаткові операції:</b> складання, маркування, пакування за вашими вимогами.</li>"], ["blockquote", "<p>Для серійного виробу ціна деталі майже завжди падає зі зростанням тиражу: машинний час налагодження й вартість пресформи розподіляються на більшу кількість виробів.</p>"], ["h2", "Мінімальний тираж"], ["p", "Лиття під тиском найвигідніше від кількох тисяч деталей. Але мінімальний тираж залежить від виробу: для простих деталей у готовій пресформі партія може бути меншою, для нового виробу ми можемо почати з пробної партії, щоб ви перевірили деталь перед серією."], ["p", "Якщо обсяг поки невеликий, підкажемо, як спростити конструкцію пресформи, щоб старт коштував дешевше."], ["h2", "Терміни"], ["ul", "<li><b>Є пресформа, виріб уже випускався:</b> терміни залежать від обсягу партії й завантаження обладнання — фіксуємо їх у комерційній пропозиції.</li><li><b>Є ваша пресформа, але ми її ще не використовували:</b> перевірка форми, підбір режимів і пробне лиття займають кілька днів.</li><li><b>Пресформи немає:</b> найдовший етап — її проєктування й виготовлення, зазвичай кілька тижнів. Про це — в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення»</a>.</li>"], ["cta", "{\"t\": \"Розрахуємо лиття вашого виробу\", \"d\": \"Надішліть креслення, 3D-модель або зразок — підготуємо ціну деталі, вартість пресформи та терміни.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Як отримати точний розрахунок"], ["ol", "<li>Надішліть креслення або 3D-модель (STEP, IGES) чи фото зразка з розмірами.</li><li>Вкажіть матеріал або умови роботи деталі: навантаження, температура, вулиця чи приміщення.</li><li>Назвіть плановий обсяг — партію й річну потребу.</li><li>Додайте вимоги до кольору, поверхні та пакування.</li>"], ["p", "Менеджер у робочий час зв’яжеться з вами, уточнить деталі й підготує комерційну пропозицію."], ["h2", "Чому замовляють у PLASTIZA"], ["ul", "<li><b>Власне виробництво у Львові</b> — без посередників між вами й термопластавтоматом.</li><li><b>Повний цикл:</b> аналіз креслення, пресформа, пробне лиття, серія, пакування й доставка.</li><li><b>Досвід серійного випуску</b> будівельних фіксаторів, де важливі стабільні розміри кожної партії.</li><li><b>Пресформа належить замовнику</b> — ви не прив’язані до виробника.</li><li><b>Доставка по Україні</b> та документи для юридичних осіб.</li>"], ["p", "Детальніше про обладнання — на сторінці <a href=\"/vyrobnytstvo\" data-go=\"about\">«Виробництво»</a>."], ["h2", "Часті питання"], ["h3", "Скільки коштує лиття однієї деталі?"], ["p", "Однієї ціни немає: вона залежить від маси, матеріалу, часу циклу й тиражу. Точний розрахунок робимо за кресленням або зразком."], ["h3", "Чи можна замовити лиття без пресформи?"], ["p", "Пресформа потрібна для лиття під тиском. Якщо її немає, ми спроєктуємо й виготовимо її під ваш виріб."], ["h3", "Ви працюєте з клієнтами з інших міст?"], ["p", "Так, працюємо з усією Україною: креслення приймаємо онлайн, готову продукцію доставляємо службами доставки або перевізниками."], ["h2", "Висновок"], ["p", "Ціну лиття пластикових виробів визначають матеріал, час циклу, кількість гнізд, тираж і пресформа. Що більше даних ви надасте, то точніший розрахунок. Заповніть форму нижче — і ми підготуємо пропозицію на лиття вашого виробу у Львові."]], [["p", "When a company needs a batch of plastic parts — housings, caps, fasteners, spacers or technical components — the first question is always the same: how much will it cost and how soon will it be ready? The answer depends on a few factors, and knowing them in advance helps you save money and avoid delays."], ["p", "This article explains how the price of custom plastic molding is formed, which lead times are realistic, from what run size molding pays off and what we need to give you an exact quote at our Lviv plant. More about the service: <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">Plastic injection molding</a>."], ["h2", "What we mold"], ["p", "On our own injection molding machines PLASTIZA molds thermoplastic parts for construction, industry and consumer use:"], ["ul", "<li>technical parts, fasteners, bushings, caps;</li><li>housings and covers;</li><li>construction products — rebar spacers and formwork accessories;</li><li>parts to customer drawings or from a sample.</li>"], ["p", "We work with our own molds and with customer molds. The full path from drawing to series is described in <a href=\"/en/blog/injection-molding-process\" data-go=\"post\" data-a=\"3\">“Plastic injection molding”</a>."], ["h2", "What the price is made of"], ["ul", "<li><b>Material and part weight.</b> Heavier parts and dearer plastics mean a larger raw-material share.</li><li><b>Cycle time.</b> Thick walls cool longer and take more machine time per part.</li><li><b>Number of cavities.</b> A four-cavity mold makes four parts per cycle and lowers the unit price.</li><li><b>The mold.</b> If there is none yet, its cost is spread over the run or paid separately.</li><li><b>Secondary operations:</b> assembly, marking and packing to your requirements.</li>"], ["blockquote", "<p>For a series part, the unit price almost always falls as the run grows: setup time and mold cost are spread over more parts.</p>"], ["h2", "Minimum run"], ["p", "Injection molding pays off from several thousand parts. But the minimum depends on the part: simple parts in an existing mold can run in smaller batches, and for a new part we can start with a trial batch so you can test it before the series."], ["p", "If volumes are still small, we will suggest how to simplify the mold so the start costs less."], ["h2", "Lead times"], ["ul", "<li><b>The mold exists and the part has run before:</b> timing depends on batch size and machine load — fixed in the quote.</li><li><b>You have a mold we have not used yet:</b> mold check, process setup and trial shots take a few days.</li><li><b>No mold yet:</b> its design and manufacture is the longest stage, usually a few weeks. See <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold”</a>.</li>"], ["cta", "{\"t\": \"We will quote your part\", \"d\": \"Send a drawing, 3D model or sample — we will prepare the part price, mold cost and lead time.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "How to get an exact quote"], ["ol", "<li>Send a drawing or 3D model (STEP, IGES) or photos of a sample with dimensions.</li><li>State the material or the part’s operating conditions: load, temperature, indoor or outdoor.</li><li>Give the planned volume — batch size and annual demand.</li><li>Add colour, surface and packing requirements.</li>"], ["p", "A manager will contact you during working hours, clarify the details and send a quote."], ["h2", "Why customers choose PLASTIZA"], ["ul", "<li><b>Own production in Lviv</b> — no middlemen between you and the machine.</li><li><b>Full cycle:</b> drawing review, mold, trial shots, series, packing and delivery.</li><li><b>Series experience</b> with construction spacers, where stable dimensions in every batch matter.</li><li><b>The mold belongs to the customer</b> — you are not tied to the manufacturer.</li><li><b>Delivery across Ukraine</b> and full paperwork for businesses.</li>"], ["p", "More on our equipment: <a href=\"/en/production\" data-go=\"about\">Production</a>."], ["h2", "FAQ"], ["h3", "How much does one part cost?"], ["p", "There is no single price: it depends on weight, material, cycle time and run size. We quote from a drawing or sample."], ["h3", "Can you mold without a mold?"], ["p", "Injection molding needs a mold. If you do not have one, we will design and build it for your part."], ["h3", "Do you work with customers in other cities?"], ["p", "Yes, across Ukraine: we accept drawings online and deliver finished parts by courier or freight."], ["h2", "Conclusion"], ["p", "The price of molded plastic parts is set by material, cycle time, cavities, run size and the mold. The more data you provide, the more accurate the quote. Fill in the form below and we will prepare an offer for molding your part in Lviv."]]]}, {"id": 13, "st": "pub", "img": "/assets/img/blog/vyhotovlennia-presform.webp", "tag": ["Пресформи", "Molds"], "date": "2026-05-19", "slug": {"uk": "vyhotovlennia-presform-vid-kreslennia-do-partii", "en": "mold-making-from-drawing-to-first-batch"}, "t": ["Виготовлення пресформ для лиття пластику: як ми проходимо шлях від креслення до першої партії", "Mold making for plastic injection: how we go from drawing to the first batch"], "e": ["Як PLASTIZA виготовляє пресформи на замовлення: аналіз виробу, проєктування, виготовлення, пробне лиття й запуск серії. Що отримує замовник на кожному етапі.", "How PLASTIZA makes custom injection molds: part review, design, manufacturing, trial shots and series launch — and what the customer gets at each stage."], "b": [[["p", "Пресформа — це серце будь-якого пластикового виробу. Від її конструкції залежить, скільки коштуватиме кожна деталь, якою буде якість поверхні й розмірів і скільки років форма пропрацює без ремонту. Тому, обираючи виробника пресформи, важливо розуміти не лише ціну, а й те, як побудовано процес."], ["p", "У цій статті розповідаємо, як ми виготовляємо пресформи на замовлення — від першого креслення до першої серійної партії — і що замовник отримує на кожному етапі. Детальніше про послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h2", "Етап 1. Аналіз виробу й технічне завдання"], ["p", "Усе починається з креслення, 3D-моделі або зразка. Ми аналізуємо технологічність: товщину стінок, ухили, піднутрення, місце впорскування, вимоги до поверхні. На цьому етапі часто пропонуємо невеликі зміни конструкції, які спрощують форму й зменшують брак."], ["p", "<b>Що ви отримуєте:</b> висновок щодо технологічності, рекомендації та комерційну пропозицію з вартістю й термінами."], ["h2", "Етап 2. Проєктування пресформи"], ["p", "Інженери створюють 3D-модель пресформи: формоутворні вставки, ливникову систему, охолодження, систему виштовхування й рухомі елементи. Кількість гнізд підбираємо під ваш річний обсяг, щоб збалансувати вартість форми й ціну деталі."], ["p", "<b>Що ви отримуєте:</b> погодження конструкції перед виготовленням — зміни на цьому етапі коштують найменше."], ["h2", "Етап 3. Виготовлення"], ["p", "Деталі пресформи обробляють на верстатах із ЧПК, виконують електроерозійну обробку, шліфування й термообробку формоутворних частин. Потім форму збирають і перевіряють рухомі елементи та канали охолодження."], ["blockquote", "<p>Найдешевше виправити помилку на кресленні, дорожче — у металі, і найдорожче — у готовій партії. Тому перші два етапи для нас не формальність.</p>"], ["h2", "Етап 4. Пробне лиття й доведення"], ["p", "Форму встановлюють на термопластавтомат і відливають перші деталі. Технолог підбирає режими, ми вимірюємо зразки й за потреби доводимо форму, доки деталь не відповідатиме кресленню."], ["p", "<b>Що ви отримуєте:</b> пробні зразки для перевірки розмірів, складання й зовнішнього вигляду."], ["h2", "Етап 5. Серія або передача форми"], ["p", "Після погодження зразків є два варіанти:"], ["ul", "<li>ми запускаємо серійне лиття на нашому обладнанні у Львові й постачаємо вам готові вироби — <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">послуга лиття</a>;</li><li>ми передаємо пресформу вам для використання на вашому підприємстві.</li>"], ["p", "Пресформа, оплачена замовником, належить замовнику."], ["cta", "{\"t\": \"Маєте виріб для нової пресформи?\", \"d\": \"Надішліть креслення, 3D-модель або зразок — підготуємо пропозицію на пресформу й лиття.\", \"b\": [[\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Від чого залежать вартість і терміни"], ["ul", "<li>розміри й складність виробу;</li><li>кількість гнізд;</li><li>піднутрення й рухомі елементи (повзуни, знаки);</li><li>тип ливникової системи;</li><li>вимоги до ресурсу, точності й поверхні.</li>"], ["p", "Проста форма виготовляється за кілька тижнів, складна багатогніздна — довше. Що підготувати до звернення, щоб розрахунок був точним, ми розписали в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення»</a>."], ["h2", "Часті питання"], ["h3", "Чи можна виготовити пресформу за зразком без креслення?"], ["p", "Так. Ми виконаємо обмір, побудуємо 3D-модель і погодимо її з вами перед проєктуванням форми."], ["h3", "Чи робите ви ремонт пресформ?"], ["p", "Так, оцінюємо стан форми й пропонуємо ремонт або модернізацію. Детальніше — у статті <a href=\"/blog/remont-i-modernizatsiia-presform\" data-go=\"post\" data-a=\"16\">«Ремонт і модернізація пресформ»</a>."], ["h3", "Чи можна змінити виріб після виготовлення пресформи?"], ["p", "Частково: зміни, що зводяться до видалення металу, зазвичай можливі. Тому ключові рішення краще погодити на етапі проєктування."], ["h2", "Висновок"], ["p", "Пресформа на замовлення проходить п’ять етапів: аналіз, проєктування, виготовлення, пробне лиття й запуск. На кожному з них ви бачите результат і погоджуєте наступний крок. Залиште заявку нижче — і ми підготуємо розрахунок пресформи для вашого виробу."]], [["p", "The mold is the heart of any plastic product. Its design determines what every part costs, how good the surface and dimensions are and how many years the mold runs without repair. So when choosing a mold maker, it matters to understand not only the price but how the process is built."], ["p", "This article explains how we make custom molds — from the first drawing to the first series batch — and what you get at each stage. More about the service: <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">Mold making</a>."], ["h2", "Stage 1. Part review and brief"], ["p", "Everything starts with a drawing, 3D model or sample. We review manufacturability: wall thickness, draft, undercuts, gate location, surface requirements. At this stage we often suggest small design changes that simplify the mold and reduce rejects."], ["p", "<b>You get:</b> a manufacturability review, recommendations and a quote with cost and timing."], ["h2", "Stage 2. Mold design"], ["p", "Engineers build a 3D model of the mold: cavity inserts, runner system, cooling, ejection and moving elements. The number of cavities is matched to your annual volume to balance mold cost and part price."], ["p", "<b>You get:</b> design approval before manufacturing — changes cost least at this stage."], ["h2", "Stage 3. Manufacturing"], ["p", "Mold parts are CNC machined, EDM-processed, ground and heat-treated. The mold is then assembled and moving elements and cooling channels are checked."], ["blockquote", "<p>Fixing a mistake on the drawing is cheapest, in steel it costs more, and in a finished batch it costs most. That is why the first two stages are not a formality for us.</p>"], ["h2", "Stage 4. Trial shots and tuning"], ["p", "The mold goes onto an injection molding machine and the first parts are molded. The process engineer sets the parameters, we measure samples and fine-tune the mold until the part matches the drawing."], ["p", "<b>You get:</b> trial samples to check dimensions, assembly and appearance."], ["h2", "Stage 5. Series or handover"], ["p", "After sample approval there are two options:"], ["ul", "<li>we start series molding on our equipment in Lviv and supply finished parts — <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">molding service</a>;</li><li>we hand the mold over for use at your plant.</li>"], ["p", "A mold paid for by the customer belongs to the customer."], ["cta", "{\"t\": \"Have a part that needs a new mold?\", \"d\": \"Send a drawing, 3D model or sample — we will quote the mold and molding.\", \"b\": [[\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "What drives cost and lead time"], ["ul", "<li>part size and complexity;</li><li>number of cavities;</li><li>undercuts and moving elements (slides, lifters);</li><li>runner type;</li><li>tool life, precision and surface requirements.</li>"], ["p", "A simple mold takes a few weeks; a complex multi-cavity tool takes longer. What to prepare for an accurate quote is covered in <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold”</a>."], ["h2", "FAQ"], ["h3", "Can you make a mold from a sample without drawings?"], ["p", "Yes. We measure the sample, build a 3D model and agree it with you before designing the mold."], ["h3", "Do you repair molds?"], ["p", "Yes, we assess the mold and propose repair or upgrade. See <a href=\"/en/blog/mold-repair-and-upgrade\" data-go=\"post\" data-a=\"16\">“Mold repair and upgrade”</a>."], ["h3", "Can the part be changed after the mold is made?"], ["p", "Partly: changes that mean removing steel are usually possible. Key decisions are best agreed at the design stage."], ["h2", "Conclusion"], ["p", "A custom mold goes through five stages: review, design, manufacturing, trial shots and launch. At each one you see the result and approve the next step. Leave a request below and we will quote a mold for your part."]]]}, {"id": 14, "st": "pub", "img": "/assets/img/blog/kontraktne-vyrobnytstvo.webp", "tag": ["Виробництво", "Production"], "date": "2026-06-23", "slug": {"uk": "yak-zapustyty-vlasnyi-plastykovyi-produkt", "en": "launch-your-own-plastic-product"}, "t": ["Як запустити власний пластиковий продукт без власного цеху: від ідеї до серійної партії", "How to launch your own plastic product without a factory: from idea to series batch"], "e": ["Покроковий план для підприємців і виробників: як перетворити ідею пластикового виробу на серійну продукцію без купівлі обладнання — модель, прототип, пресформа, лиття, пакування.", "A step-by-step plan for entrepreneurs and manufacturers to turn a plastic product idea into series production without buying equipment — model, prototype, mold, molding, packing."], "b": [[["p", "Багато сильних продуктів починаються з простої ідеї: зручніше кріплення, міцніша заглушка, власний аксесуар для лінійки товарів. Але між ідеєю і полицею — виробництво, і саме воно лякає найбільше: термопластавтомати, пресформи, технологи, сировина. Добра новина — купувати все це не обов’язково."], ["p", "У цій статті розповідаємо, як запустити власний пластиковий продукт без власного цеху, з контрактним виробником, і які кроки пройти, щоб не втратити час і гроші."], ["h2", "Крок 1. Сформулюйте вимоги до виробу"], ["p", "Перш ніж малювати, запишіть, що виріб має робити: навантаження, температура, контакт із водою чи хімією, вулиця чи приміщення, колір, вимоги до вигляду. Від цього залежать матеріал і конструкція."], ["h2", "Крок 2. Креслення або 3D-модель"], ["p", "Для розрахунку й виготовлення пресформи потрібна модель. Якщо у вас є лише ескіз або зразок аналогу, ми допоможемо: виконаємо обмір і побудуємо 3D-модель. На цьому ж етапі варто врахувати технологічність — рівні стінки, ухили, радіуси."], ["h2", "Крок 3. Прототип"], ["p", "Якщо конструкція ще не остаточна, перевірте її на прототипі: зібрати, примірити, показати клієнтам. Зміна в моделі коштує копійки порівняно зі зміною в металі пресформи."], ["blockquote", "<p>Найчастіша помилка новачків — замовити пресформу «одразу начисто», а потім переробляти її після перших відгуків покупців.</p>"], ["h2", "Крок 4. Пресформа"], ["p", "Пресформа — найбільша стартова інвестиція. Щоб вона окупилася, кількість гнізд і ресурс підбирають під реальний обсяг продажів, а не «на виріст». Як ми проєктуємо й виготовляємо форми, читайте в статті <a href=\"/blog/vyhotovlennia-presform-vid-kreslennia-do-partii\" data-go=\"post\" data-a=\"13\">«Виготовлення пресформ: від креслення до першої партії»</a>."], ["h2", "Крок 5. Пробна партія"], ["p", "Перші деталі з пресформи — це ще й маркетинговий інструмент: їх можна показати дистриб’юторам, протестувати в реальних умовах і зібрати перші замовлення до запуску великої серії."], ["h2", "Крок 6. Серія, пакування й логістика"], ["p", "Після погодження зразків запускаємо серійне лиття. За потреби пакуємо вироби під ваші вимоги й доставляємо по Україні. Вам залишається продавати."], ["cta", "{\"t\": \"Маєте ідею пластикового виробу?\", \"d\": \"Розкажіть про продукт — підкажемо, з чого почати, і порахуємо пресформу та першу партію.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Обговорити проєкт\", \"rfq\"]]}"], ["h2", "Скільки коштує старт"], ["p", "Бюджет запуску складається з трьох частин:"], ["ul", "<li><b>модель і прототип</b> — найменша частка, але вона економить найбільше;</li><li><b>пресформа</b> — основна інвестиція, залежить від розмірів і складності виробу та кількості гнізд;</li><li><b>перша партія</b> — матеріал і машинний час.</li>"], ["p", "Пресформа, яку ви оплатили, належить вам. Ціна деталі знижується зі зростанням тиражу, тому продукт стає вигіднішим, щойно продажі ростуть. Що впливає на вартість лиття, ми розписали в статті <a href=\"/blog/lyttia-plastykovykh-vyrobiv-na-zamovlennia-lviv\" data-go=\"post\" data-a=\"12\">«Лиття пластикових виробів на замовлення: ціна й терміни»</a>."], ["h2", "Чому контрактне виробництво вигідне на старті"], ["ul", "<li>не потрібно купувати обладнання й наймати технологів;</li><li>витрати пропорційні обсягам продажів;</li><li>швидкий запуск — за тижні, а не за місяці;</li><li>можна протестувати ринок невеликою партією.</li>"], ["p", "Як обрати надійного виробника, ми розповідали в статті <a href=\"/blog/kontraktne-lyttia-plastyku\" data-go=\"post\" data-a=\"11\">«Контрактне лиття пластику в Україні»</a>."], ["h2", "Часті питання"], ["h3", "Чи можна почати з невеликого тиражу?"], ["p", "Так. Часто старт роблять із пробної партії, а потім переходять до серії. Підкажемо, як оптимізувати пресформу під невеликі обсяги."], ["h3", "Хто відповідає за конструкцію виробу?"], ["p", "Конструкцію визначаєте ви, а ми перевіряємо її технологічність і пропонуємо зміни, які спростять виробництво."], ["h3", "Чи захищені мої креслення?"], ["p", "Ми використовуємо ваші креслення лише для вашого замовлення. За потреби угоду про нерозголошення можна обговорити з менеджером."], ["h2", "Висновок"], ["p", "Власний пластиковий продукт можна запустити без цеху: сформулювати вимоги, підготувати модель, перевірити прототип, виготовити пресформу й запустити лиття з контрактним виробником. Розкажіть нам про свій виріб у формі нижче — і ми запропонуємо план запуску з розрахунком."]], [["p", "Many strong products start with a simple idea: a handier fastener, a tougher cap, your own accessory for a product line. But between the idea and the shelf lies production — machines, molds, process engineers, raw materials. The good news: you do not have to buy any of it."], ["p", "This article explains how to launch your own plastic product with a contract manufacturer, and which steps to take so you do not lose time or money."], ["h2", "Step 1. Define the requirements"], ["p", "Before drawing, write down what the part must do: load, temperature, contact with water or chemicals, indoor or outdoor, colour, appearance. Material and design depend on this."], ["h2", "Step 2. Drawing or 3D model"], ["p", "A model is needed to quote and build the mold. If you only have a sketch or a sample of something similar, we will measure it and build a 3D model. Design for manufacturing at this stage too — even walls, draft, radii."], ["h2", "Step 3. Prototype"], ["p", "If the design is not final, test it with a prototype: assemble it, try it, show it to customers. A change in the model costs very little compared with a change in mold steel."], ["blockquote", "<p>The most common beginner mistake is ordering a “final” mold straight away and reworking it after the first customer feedback.</p>"], ["h2", "Step 4. The mold"], ["p", "The mold is the biggest start-up investment. To pay back, its cavities and tool life are matched to realistic sales, not “room to grow”. How we design and build molds: <a href=\"/en/blog/mold-making-from-drawing-to-first-batch\" data-go=\"post\" data-a=\"13\">“Mold making: from drawing to first batch”</a>."], ["h2", "Step 5. Trial batch"], ["p", "The first parts from the mold are also a sales tool: show them to distributors, test them in real conditions and collect first orders before a large run."], ["h2", "Step 6. Series, packing and logistics"], ["p", "After sample approval we start series molding, pack parts to your requirements and deliver across Ukraine. You focus on selling."], ["cta", "{\"t\": \"Have a plastic product idea?\", \"d\": \"Tell us about it — we will suggest where to start and quote the mold and first batch.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Discuss the project\", \"rfq\"]]}"], ["h2", "What the start costs"], ["p", "The launch budget has three parts:"], ["ul", "<li><b>model and prototype</b> — the smallest share, but it saves the most;</li><li><b>the mold</b> — the main investment, depending on part size, complexity and cavities;</li><li><b>the first batch</b> — material and machine time.</li>"], ["p", "The mold you paid for is yours. The part price falls as runs grow, so the product becomes more profitable as sales grow. What drives molding cost is covered in <a href=\"/en/blog/custom-plastic-injection-molding-lviv\" data-go=\"post\" data-a=\"12\">“Custom plastic injection molding: price and lead times”</a>."], ["h2", "Why contract production pays off at the start"], ["ul", "<li>no equipment to buy and no process engineers to hire;</li><li>costs scale with sales;</li><li>fast launch — weeks, not months;</li><li>you can test the market with a small batch.</li>"], ["p", "How to choose a reliable manufacturer: <a href=\"/en/blog/contract-injection-molding-ukraine\" data-go=\"post\" data-a=\"11\">“Contract plastic injection molding in Ukraine”</a>."], ["h2", "FAQ"], ["h3", "Can I start with a small run?"], ["p", "Yes. Many start with a trial batch and then move to a series. We will suggest how to optimise the mold for small volumes."], ["h3", "Who is responsible for the part design?"], ["p", "You define the design; we check manufacturability and suggest changes that simplify production."], ["h3", "Are my drawings protected?"], ["p", "We use your drawings only for your order. A non-disclosure agreement can be discussed with your manager if needed."], ["h2", "Conclusion"], ["p", "You can launch your own plastic product without a factory: define requirements, prepare a model, test a prototype, build a mold and start molding with a contract manufacturer. Tell us about your part in the form below and we will propose a launch plan with a quote."]]]}, {"id": 15, "st": "pub", "img": "/assets/img/blog/zamina-importnykh-detalei.webp", "tag": ["Виробництво", "Production"], "date": "2026-07-28", "slug": {"uk": "zamina-importnykh-plastykovykh-detalei", "en": "replacing-imported-plastic-parts"}, "t": ["Заміна імпортних пластикових деталей: як перенести виробництво з Китаю в Україну", "Replacing imported plastic parts: how to move production from China to Ukraine"], "e": ["Чому компанії переносять лиття пластикових деталей з Азії в Україну, як виготовити деталь за зразком без креслень і що потрібно, щоб перейти на українського виробника без зупинки поставок.", "Why companies move plastic part molding from Asia to Ukraine, how to make a part from a sample without drawings and how to switch to a Ukrainian manufacturer without interrupting supply."], "b": [[["p", "Ще кілька років тому замовлення пластикових деталей у Китаї здавалося безальтернативним: низька ціна за штуку перекривала все. Сьогодні багато компаній рахують інакше — з урахуванням логістики, термінів, мінімальних партій, курсових ризиків і заморожених на складі грошей. І все частіше переносять лиття ближче до себе — в Україну."], ["p", "У цій статті розповідаємо, коли заміна імпортних пластикових деталей вигідна, як виготовити деталь за зразком без креслень і як перейти на українського виробника без зупинки поставок."], ["h2", "Чому компанії переносять виробництво"], ["ul", "<li><b>Терміни.</b> Доставка з Азії займає тижні, а будь-яка затримка зупиняє ваш конвеєр чи продажі.</li><li><b>Мінімальні партії.</b> Іноземні фабрики часто вимагають великих тиражів, і гроші місяцями лежать на складі.</li><li><b>Логістика й мито</b> збільшують реальну ціну деталі.</li><li><b>Комунікація.</b> Узгодити зміну чи розібратися з браком значно простіше, коли виробник у твоїй країні.</li><li><b>Контроль якості.</b> Можна приїхати на виробництво й побачити процес.</li>"], ["blockquote", "<p>Порівнюйте не ціну деталі на заводі, а повну вартість: доставку, мито, заморожені гроші, ризик затримок і брак.</p>"], ["h2", "Деталь за зразком: якщо креслень немає"], ["p", "Найчастіша ситуація — у вас є лише сама деталь, а креслень і пресформи немає (вона лишилася у виробника за кордоном). Це не проблема:"], ["ol", "<li>Ви надсилаєте зразки деталі.</li><li>Ми виконуємо обмір і будуємо 3D-модель.</li><li>Погоджуємо модель з вами і, за потреби, покращуємо слабкі місця оригіналу.</li><li>Проєктуємо й виготовляємо нову пресформу — <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">послуга виготовлення пресформ</a>.</li><li>Відливаємо пробну партію й порівнюємо з оригіналом.</li>"], ["h2", "Матеріал"], ["p", "Важливо підібрати пластик, який відповідає оригіналу за властивостями: міцністю, гнучкістю, стійкістю до температури чи УФ. Якщо марка невідома, ми підберемо аналог за умовами роботи деталі."], ["h2", "Як перейти без зупинки поставок"], ["ul", "<li>Почніть процес, поки у вас ще є запас імпортних деталей.</li><li>Погодьте пробну партію й випробуйте її у вашому виробі.</li><li>Запускайте серію до того, як закінчиться складський запас.</li><li>Плануйте наступні партії з урахуванням коротших термінів — склад можна зменшити.</li>"], ["cta", "{\"t\": \"Хочете замінити імпортну деталь?\", \"d\": \"Надішліть зразок або фото з розмірами — оцінимо, підготуємо модель і розрахуємо пресформу й лиття.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Надіслати зразок\", \"rfq\"]]}"], ["h2", "Що ми пропонуємо"], ["ul", "<li>виготовлення деталей за зразком, кресленням або 3D-моделлю;</li><li>проєктування й виготовлення пресформ, що належать замовнику;</li><li>серійне лиття на нашому обладнанні у Львові — <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">послуга лиття</a>;</li><li>пакування й доставку по Україні, документи для юридичних осіб.</li>"], ["p", "Як обрати виробника для контрактного лиття, ми розповідали в статті <a href=\"/blog/kontraktne-lyttia-plastyku\" data-go=\"post\" data-a=\"11\">«Контрактне лиття пластику в Україні»</a>."], ["h2", "Часті питання"], ["h3", "Чи можна відлити деталь у пресформі, привезеній з-за кордону?"], ["p", "Так, якщо вона сумісна з нашим обладнанням. Ми перевіримо форму, підберемо режими й зробимо пробне лиття."], ["h3", "Скільки зразків потрібно для обміру?"], ["p", "Зазвичай достатньо кількох штук: одну можна використати для обміру, інші — для порівняння з пробною партією."], ["h3", "Чи вийде дешевше, ніж у Китаї?"], ["p", "Ціна деталі на заводі може бути співставною або трохи вищою, але повна вартість з урахуванням логістики, термінів і запасів часто виявляється нижчою. Порахуємо для вашого випадку."], ["h2", "Висновок"], ["p", "Перенести лиття пластикових деталей в Україну можна навіть без креслень: за зразком ми підготуємо модель, виготовимо пресформу й запустимо серію. Почніть, поки є запас імпортних деталей, — і перейдете без зупинки поставок. Залиште заявку нижче з описом деталі."]], [["p", "A few years ago ordering plastic parts in China seemed the only option: the low unit price outweighed everything. Today many companies count differently — including logistics, lead times, minimum orders, currency risk and cash frozen in stock. And more and more of them move molding closer to home — to Ukraine."], ["p", "This article explains when replacing imported plastic parts pays off, how to make a part from a sample without drawings and how to switch suppliers without stopping supply."], ["h2", "Why companies move production"], ["ul", "<li><b>Lead times.</b> Shipping from Asia takes weeks, and any delay stops your line or sales.</li><li><b>Minimum orders.</b> Foreign factories often require large runs, and cash sits in stock for months.</li><li><b>Logistics and duties</b> raise the real part price.</li><li><b>Communication.</b> Agreeing changes or resolving defects is far easier with a manufacturer in your own country.</li><li><b>Quality control.</b> You can visit the plant and see the process.</li>"], ["blockquote", "<p>Compare not the ex-works part price but the total cost: shipping, duties, frozen cash, delay risk and rejects.</p>"], ["h2", "A part from a sample: no drawings needed"], ["p", "The most common situation: you only have the part itself, with no drawings or mold (it stayed with the overseas factory). That is not a problem:"], ["ol", "<li>You send samples of the part.</li><li>We measure them and build a 3D model.</li><li>We agree the model with you and, if needed, improve weak points of the original.</li><li>We design and build a new mold — <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">mold making service</a>.</li><li>We mold a trial batch and compare it with the original.</li>"], ["h2", "Material"], ["p", "It is important to match the original’s properties: strength, flexibility, temperature or UV resistance. If the grade is unknown, we choose an equivalent for the part’s operating conditions."], ["h2", "Switching without stopping supply"], ["ul", "<li>Start while you still have imported parts in stock.</li><li>Approve a trial batch and test it in your product.</li><li>Launch the series before stock runs out.</li><li>Plan further batches around shorter lead times — you can hold less stock.</li>"], ["cta", "{\"t\": \"Want to replace an imported part?\", \"d\": \"Send a sample or photos with dimensions — we will assess it, prepare a model and quote the mold and molding.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Send a sample\", \"rfq\"]]}"], ["h2", "What we offer"], ["ul", "<li>parts made from a sample, drawing or 3D model;</li><li>design and manufacture of molds owned by the customer;</li><li>series molding on our equipment in Lviv — <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">molding service</a>;</li><li>packing, delivery across Ukraine and paperwork for businesses.</li>"], ["p", "How to choose a contract molder: <a href=\"/en/blog/contract-injection-molding-ukraine\" data-go=\"post\" data-a=\"11\">“Contract plastic injection molding in Ukraine”</a>."], ["h2", "FAQ"], ["h3", "Can you mold in a mold brought from abroad?"], ["p", "Yes, if it fits our machines. We check the mold, set the process and run trial shots."], ["h3", "How many samples do you need?"], ["p", "Usually a few: one for measuring, others for comparison with the trial batch."], ["h3", "Will it be cheaper than China?"], ["p", "The ex-works part price may be similar or slightly higher, but the total cost including logistics, lead time and stock often turns out lower. We will calculate it for your case."], ["h2", "Conclusion"], ["p", "You can move plastic part molding to Ukraine even without drawings: from a sample we prepare a model, build a mold and start the series. Begin while you still have imported stock and switch without stopping supply. Leave a request below describing your part."]]]}, {"id": 16, "st": "pub", "img": "/assets/img/blog/remont-presform.webp", "tag": ["Пресформи", "Molds"], "date": "2026-09-08", "slug": {"uk": "remont-i-modernizatsiia-presform", "en": "mold-repair-and-upgrade"}, "t": ["Ремонт і модернізація пресформ: коли вигідніше відновити стару, ніж замовляти нову", "Mold repair and upgrade: when restoring an old mold beats buying a new one"], "e": ["Ознаки зношеної пресформи, які ремонти можливі, коли модернізація окупається і як оцінити, що вигідніше — відновити форму чи виготовити нову.", "Signs of a worn injection mold, which repairs are possible, when an upgrade pays off and how to decide whether to restore the mold or make a new one."], "b": [[["p", "Пресформа працює роками, але не вічно. Облой на деталях, сліди на поверхні, підтікання, заїдання рухомих елементів — усе це сигнали, що форма потребує уваги. Багато хто одразу думає про нову пресформу, хоча часто ремонт або модернізація обходяться значно дешевше й швидше."], ["p", "У цій статті розповідаємо, за якими ознаками видно зношену пресформу, які ремонти можливі і як вирішити, що вигідніше — відновити форму чи замовити нову."], ["h2", "Ознаки, що пресформа потребує ремонту"], ["ul", "<li><b>Облой</b> — тонкий «ласт» по лінії рознімання через знос площин змикання.</li><li><b>Сліди, подряпини чи матовість</b> на поверхні деталі.</li><li><b>Нестабільні розміри</b> від партії до партії.</li><li><b>Заїдання</b> повзунів, знаків, виштовхувачів.</li><li><b>Підтікання</b> в системі охолодження.</li><li><b>Збільшений час циклу</b>, щоб отримати якісну деталь.</li>"], ["blockquote", "<p>Чим раніше помітити знос, тим дешевший ремонт. Облой, на який не звертали уваги, з часом руйнує площини змикання.</p>"], ["h2", "Які роботи можливі"], ["h3", "Ремонт"], ["ul", "<li>відновлення площин змикання й усунення облою;</li><li>заміна зношених виштовхувачів, втулок, напрямних;</li><li>ремонт рухомих елементів;</li><li>відновлення формоутворної поверхні, полірування;</li><li>ремонт каналів охолодження.</li>"], ["h3", "Модернізація"], ["ul", "<li>зміна виробу — подовження, поглиблення, нові отвори (якщо зміни зводяться до видалення металу);</li><li>додавання гнізд або змінних вставок під нові типорозміри;</li><li>покращення охолодження для скорочення циклу;</li><li>заміна ливникової системи.</li>"], ["h2", "Ремонт чи нова пресформа: як вирішити"], ["p", "Ремонт вигідний, якщо:"], ["ul", "<li>основний корпус і формоутворні частини в задовільному стані;</li><li>проблема локальна — облой, знос виштовхувачів, полірування;</li><li>виріб не змінюється кардинально.</li>"], ["p", "Нова форма доцільніша, якщо:"], ["ul", "<li>формоутворні вставки сильно зношені або пошкоджені;</li><li>виріб суттєво змінюється;</li><li>потрібно значно збільшити продуктивність — більше гнізд, гарячі канали.</li>"], ["p", "Ми оцінюємо стан форми й пропонуємо обидва варіанти з вартістю й термінами, щоб ви бачили різницю. Якщо вирішите робити нову, процес описано в статті <a href=\"/blog/vyhotovlennia-presform-vid-kreslennia-do-partii\" data-go=\"post\" data-a=\"13\">«Виготовлення пресформ: від креслення до першої партії»</a>."], ["cta", "{\"t\": \"Потрібен ремонт пресформи?\", \"d\": \"Надішліть фото форми й деталі з дефектом — оцінимо стан і запропонуємо ремонт, модернізацію або нову форму.\", \"b\": [[\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Надіслати фото\", \"rfq\"]]}"], ["h2", "Як продовжити життя пресформи"], ["ul", "<li>регулярно чистіть площини змикання й вентиляційні канали;</li><li>змащуйте рухомі елементи;</li><li>контролюйте стан системи охолодження;</li><li>зберігайте форму з консервацією між тиражами;</li><li>не ігноруйте перший облой.</li>"], ["p", "Якщо форма зберігається в нас, ми обслуговуємо її між партіями — і ви отримуєте стабільну якість кожного тиражу."], ["h2", "Часті питання"], ["h3", "Чи ремонтуєте ви пресформи, виготовлені іншими виробниками?"], ["p", "Так. Ми оцінюємо стан будь-якої форми, сумісної з нашим обладнанням, і пропонуємо варіанти ремонту."], ["h3", "Скільки триває ремонт?"], ["p", "Залежить від обсягу робіт: дрібний ремонт — від кількох днів, модернізація — довше. Терміни називаємо після огляду."], ["h3", "Чи можна після ремонту одразу відлити партію?"], ["p", "Так. Після ремонту робимо пробне лиття і, за погодженням, запускаємо партію на нашому обладнанні — <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">послуга лиття</a>."], ["h2", "Висновок"], ["p", "Облой, сліди на поверхні й нестабільні розміри — сигнал перевірити пресформу. Часто ремонт або модернізація обходяться дешевше за нову форму і повертають якість деталей. Надішліть нам фото форми й дефектної деталі — оцінимо й запропонуємо оптимальне рішення."]], [["p", "A mold runs for years, but not forever. Flash on parts, surface marks, leaks, sticking moving elements — all signal that the mold needs attention. Many people immediately think of a new mold, although repair or upgrade is often much cheaper and faster."], ["p", "This article covers the signs of a worn mold, the repairs that are possible and how to decide what pays off better — restoring the mold or ordering a new one."], ["h2", "Signs a mold needs repair"], ["ul", "<li><b>Flash</b> — thin fins on the parting line from worn shut-off surfaces.</li><li><b>Marks, scratches or dullness</b> on the part surface.</li><li><b>Unstable dimensions</b> from batch to batch.</li><li><b>Sticking</b> slides, lifters or ejectors.</li><li><b>Leaks</b> in the cooling system.</li><li><b>Longer cycle time</b> needed to get a good part.</li>"], ["blockquote", "<p>The earlier you catch wear, the cheaper the repair. Flash that is ignored eventually destroys the shut-off surfaces.</p>"], ["h2", "What can be done"], ["h3", "Repair"], ["ul", "<li>restoring shut-off surfaces and eliminating flash;</li><li>replacing worn ejectors, bushings and guides;</li><li>repairing moving elements;</li><li>restoring and polishing cavity surfaces;</li><li>repairing cooling channels.</li>"], ["h3", "Upgrade"], ["ul", "<li>part changes — longer, deeper, new holes (when changes mean removing steel);</li><li>adding cavities or interchangeable inserts for new sizes;</li><li>better cooling to shorten the cycle;</li><li>a new runner system.</li>"], ["h2", "Repair or a new mold: how to decide"], ["p", "Repair pays off if:"], ["ul", "<li>the mold base and cavity parts are in reasonable condition;</li><li>the problem is local — flash, worn ejectors, polishing;</li><li>the part does not change radically.</li>"], ["p", "A new mold makes more sense if:"], ["ul", "<li>cavity inserts are badly worn or damaged;</li><li>the part changes significantly;</li><li>you need much higher output — more cavities, hot runners.</li>"], ["p", "We assess the mold and propose both options with cost and timing so you can see the difference. If you go for a new mold, the process is described in <a href=\"/en/blog/mold-making-from-drawing-to-first-batch\" data-go=\"post\" data-a=\"13\">“Mold making: from drawing to first batch”</a>."], ["cta", "{\"t\": \"Need a mold repaired?\", \"d\": \"Send photos of the mold and a defective part — we will assess it and propose repair, upgrade or a new mold.\", \"b\": [[\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Send photos\", \"rfq\"]]}"], ["h2", "How to extend mold life"], ["ul", "<li>clean shut-off surfaces and vents regularly;</li><li>lubricate moving elements;</li><li>monitor the cooling system;</li><li>store the mold preserved between runs;</li><li>do not ignore the first flash.</li>"], ["p", "If your mold is stored with us, we maintain it between batches — and you get stable quality in every run."], ["h2", "FAQ"], ["h3", "Do you repair molds made by other manufacturers?"], ["p", "Yes. We assess any mold compatible with our equipment and propose repair options."], ["h3", "How long does repair take?"], ["p", "It depends on the work: minor repairs from a few days, upgrades longer. We give timing after inspection."], ["h3", "Can you mold a batch right after repair?"], ["p", "Yes. After repair we run trial shots and, if agreed, mold a batch on our equipment — <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">molding service</a>."], ["h2", "Conclusion"], ["p", "Flash, surface marks and unstable dimensions are signals to check the mold. Repair or upgrade is often cheaper than a new mold and restores part quality. Send us photos of the mold and a defective part and we will propose the best solution."]]]}, {"id": 17, "st": "pub", "img": "/assets/img/blog/komplektatsiia-obiekta.webp", "tag": ["Будівництво", "Construction"], "date": "2026-10-13", "slug": {"uk": "komplektatsiia-budivelnoho-obiekta", "en": "construction-site-supply"}, "t": ["Комплектація будівельного об’єкта: фіксатори, опалубка та матеріали від одного постачальника", "Construction site supply: spacers, formwork accessories and materials from one supplier"], "e": ["Як підряднику чи забудовнику закупити фіксатори арматури, елементи опалубки й супутні матеріали в одного постачальника: специфікація, графік поставок, документи й доставка на об’єкт.", "How a contractor or developer can buy rebar spacers, formwork accessories and related materials from one supplier: specification, delivery schedule, paperwork and delivery to site."], "b": [[["p", "На будівництві матеріали рідко закінчуються вчасно. Фіксатори докуповують у одному магазині, конуси для опалубки — в іншому, труби — в третьому. Кожна закупівля — це окремий рахунок, окрема доставка й час прораба. Комплектація об’єкта одним постачальником знімає більшість цих проблем."], ["p", "У цій статті розповідаємо, як працює комплектація будівельного об’єкта, які матеріали можна отримати в одному замовленні і як організувати поставки під етапи робіт. Детальніше про послугу — на сторінці <a href=\"/komplektatsiia-obiektiv\" data-go=\"soon\" data-a=\"2\">«Комплектація об’єктів»</a>."], ["h2", "Що таке комплектація об’єкта"], ["p", "Комплектація — це коли постачальник приймає вашу специфікацію чи кошторис і забезпечує поставку всіх позицій: власної продукції та супутніх матеріалів від перевірених партнерів. Ви отримуєте один рахунок, один графік і одного відповідального менеджера."], ["h2", "Що можна отримати в одному замовленні"], ["ul", "<li><b>Фіксатори арматури власного виробництва</b> — <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a>, <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a>, <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочка»</a>, «Защіпка», «Засувка» під захисний шар вашого проєкту;</li><li><b>Елементи для опалубки</b> — <a href=\"/dystantsiina-truba\" data-go=\"product\" data-a=\"9-0\">дистанційні труби</a> (метрами), <a href=\"/fiksator-konus\" data-go=\"product\" data-a=\"6-0\">конуси</a>, <a href=\"/fiksator-korok\" data-go=\"product\" data-a=\"8-0\">корки</a> і корки-ялинки;</li><li><b>Супутні будівельні матеріали</b> за вашою специфікацією — підбираємо через перевірених постачальників.</li>"], ["blockquote", "<p>Один постачальник — це не лише зручність. Це менше помилок у специфікаціях, менше простоїв бригади й прозорі документи для бухгалтерії.</p>"], ["h2", "Як ми працюємо"], ["ol", "<li><b>Специфікація.</b> Ви надсилаєте кошторис, специфікацію або креслення. Якщо переліку ще немає, допоможемо порахувати фіксатори — методика є в статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>.</li><li><b>Пропозиція.</b> Готуємо комерційну пропозицію за всіма позиціями з цінами й термінами.</li><li><b>Графік.</b> Погоджуємо поставки партіями під етапи: фундамент, стіни, перекриття.</li><li><b>Відвантаження.</b> Відвантажуємо зі складів у Львові та Києві й доставляємо на об’єкт.</li><li><b>Документи.</b> Рахунок, видаткові накладні й ТТН до кожної поставки.</li>"], ["cta", "{\"t\": \"Комплектуємо ваш об’єкт\", \"d\": \"Надішліть специфікацію або кошторис — підготуємо пропозицію з графіком поставок під етапи робіт.\", \"b\": [[\"Комплектація об’єктів\", \"srv2\", \"soon\", \"2\", \"/komplektatsiia-obiektiv\"], [\"Надіслати специфікацію\", \"rfq\"]]}"], ["h2", "Поставки під етапи будівництва"], ["p", "Не потрібно завозити все одразу й захаращувати майданчик. Типовий графік:"], ["ul", "<li><b>Фундамент:</b> «Настил» під нижню сітку, «Зірочки» для бічних граней.</li><li><b>Стіни й колони:</b> «Зірочки», дистанційні труби, конуси й корки для щитової опалубки.</li><li><b>Перекриття:</b> «Стійки» й «Защіпки» під нижню сітку, «Зірочки» для торців.</li>"], ["p", "Так ви платите за матеріали ближче до моменту використання, а на майданчику немає зайвих запасів."], ["h2", "Переваги для підрядника й забудовника"], ["ul", "<li>менше постачальників — менше договорів і рахунків;</li><li>ціни виробника на фіксатори й елементи опалубки;</li><li>графік поставок під етапи робіт;</li><li>повний пакет документів для безготівкового розрахунку;</li><li>доставка по всій Україні — перевізниками, транспортом партнерів або поштою.</li>"], ["p", "Про спосіб і вартість доставки читайте на сторінці <a href=\"/dostavka\" data-go=\"delivery\">«Доставка та оплата»</a>."], ["h2", "Часті питання"], ["h3", "Чи є мінімальна сума замовлення?"], ["p", "Умови залежать від складу й обсягу. Надішліть специфікацію — запропонуємо оптимальний варіант."], ["h3", "Чи можна змінити графік поставок під час будівництва?"], ["p", "Так. Графік коригуємо разом із вами, якщо змінюються етапи робіт."], ["h3", "Чи працюєте ви з тендерними закупівлями?"], ["p", "Надаємо комерційні пропозиції та документи, потрібні для закупівель. Уточніть вимоги вашого тендеру в менеджера."], ["h2", "Висновок"], ["p", "Комплектація об’єкта одним постачальником — це фіксатори, елементи опалубки й супутні матеріали в одному замовленні, поставки під етапи й прозорі документи. Надішліть специфікацію через форму нижче — підготуємо пропозицію з графіком поставок."]], [["p", "On a construction site, materials rarely run out on time. Spacers are bought in one shop, formwork cones in another, tubes in a third. Each purchase means a separate invoice, a separate delivery and the site manager’s time. Supplying a site through one supplier removes most of these problems."], ["p", "This article explains how site supply works, which materials you can get in one order and how to schedule deliveries by work stage. More about the service: <a href=\"/en/construction-supply\" data-go=\"soon\" data-a=\"2\">Site supply</a>."], ["h2", "What site supply is"], ["p", "The supplier takes your specification or bill of quantities and delivers every item: its own products plus related materials from trusted partners. You get one invoice, one schedule and one responsible manager."], ["h2", "What you can get in one order"], ["ul", "<li><b>Rebar spacers from our own production</b> — <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a>, <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a>, <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a>, “Zashchipka”, “Zasuvka” matched to your design cover;</li><li><b>Formwork accessories</b> — <a href=\"/en/spacer-tube\" data-go=\"product\" data-a=\"9-0\">spacer tubes</a> (by the metre), <a href=\"/en/cone-spacer-konus\" data-go=\"product\" data-a=\"6-0\">cones</a>, <a href=\"/en/formwork-plug-korok\" data-go=\"product\" data-a=\"8-0\">plugs</a> and fir-tree plugs;</li><li><b>Related building materials</b> to your specification, sourced from trusted suppliers.</li>"], ["blockquote", "<p>One supplier is not just convenience. It means fewer specification errors, less crew downtime and clear paperwork for accounting.</p>"], ["h2", "How we work"], ["ol", "<li><b>Specification.</b> You send a bill of quantities, specification or drawings. If there is no list yet, we will help calculate spacers — see <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a>.</li><li><b>Offer.</b> We prepare a quote for all items with prices and lead times.</li><li><b>Schedule.</b> We agree deliveries in batches by stage: foundation, walls, slabs.</li><li><b>Shipping.</b> We ship from our Lviv and Kyiv warehouses and deliver to site.</li><li><b>Paperwork.</b> Invoice, delivery notes and waybills with every shipment.</li>"], ["cta", "{\"t\": \"We will supply your site\", \"d\": \"Send a specification or bill of quantities — we will prepare an offer with a delivery schedule by work stage.\", \"b\": [[\"Site supply\", \"srv2\", \"soon\", \"2\", \"/en/construction-supply\"], [\"Send a specification\", \"rfq\"]]}"], ["h2", "Deliveries by construction stage"], ["p", "There is no need to bring everything at once and clutter the site. A typical schedule:"], ["ul", "<li><b>Foundation:</b> “Nastil” for the bottom mesh, “Zirochka” for side faces.</li><li><b>Walls and columns:</b> “Zirochka”, spacer tubes, cones and plugs for panel formwork.</li><li><b>Slabs:</b> “Stiika” and “Zashchipka” for the bottom mesh, “Zirochka” for edges.</li>"], ["p", "You pay for materials closer to when you use them, and the site holds no surplus."], ["h2", "Benefits for contractors and developers"], ["ul", "<li>fewer suppliers — fewer contracts and invoices;</li><li>manufacturer prices on spacers and formwork accessories;</li><li>a delivery schedule matched to work stages;</li><li>full paperwork for bank-transfer payment;</li><li>delivery across Ukraine — by carriers, partner transport or post.</li>"], ["p", "Delivery options and cost: <a href=\"/en/delivery\" data-go=\"delivery\">Delivery and payment</a>."], ["h2", "FAQ"], ["h3", "Is there a minimum order?"], ["p", "It depends on contents and volume. Send your specification and we will propose the best option."], ["h3", "Can the delivery schedule change during construction?"], ["p", "Yes. We adjust the schedule with you when work stages change."], ["h3", "Do you work with tenders?"], ["p", "We provide quotes and the documents needed for procurement. Check your tender’s requirements with your manager."], ["h2", "Conclusion"], ["p", "Site supply from one supplier means spacers, formwork accessories and related materials in one order, deliveries by stage and clear paperwork. Send your specification through the form below and we will prepare an offer with a delivery schedule."]]]}];
